UPDATE CRM_SERVER_MGT
	SET
	 SERVER_TYPE   =#{server_type},		CONTRACT_CONDITION =#{contract_condition} 
	 ,SERVER_NM     =#{server_nm},		FREE_START_DT      =#{free_start_dt} 
	 ,SERVER_MNF    =#{server_mnf},		FREE_END_DT        =#{free_end_dt} 
	 ,SERVER_MODEL  =#{server_model},	OS                 =#{os} 
	 ,SERVER_ID     =#{server_id},		ACCESS_TYPE        =#{access_type} 
	 ,SERVER_PASS   =#{server_pass},	RAM_TYPE           =#{ram_type} 
	 ,SERVER_IP     =#{server_ip},		RAM_NUM            =#{ram_num} 
	 ,SERVER_STATUS =#{server_status},	VACCINE_TYPE       =#{vaccine_type} 
	 ,PB_IP         =#{pb_ip},			DUR_IP             =#{dur_ip} 
	 ,UNSED_STATUS  =#{unsed_status},	DBMS_TYPE          =#{dbms_type} 
	 ,SERIAL_NUMBER =#{serial_number},	DBMS_VERSION       =#{dbms_version} 
	 ,MAIN_MNG      =#{main_mng},		DISK_TYPE          =#{disk_type} 
	 ,DISK_VOLUME   =#{disk_volume} 
	 ,WORKER_ID     =#{worker_id},		DUPLEX_CDT         =#{duplex_cdt} 
	 ,CUST_WORKER   =#{cust_worker},	THIRD_SOLUTION     =#{third_solution} 
	 ,CUST_TEL      =#{cust_tel},		RAID_TYPE          =#{raid_type} 
	 ,TAKE_DT       =#{take_dt},		DISK_NUM           =#{disk_num} 
	 ,LOCATION_PC   =#{location_pc},	DISK_INFO          =#{disk_info} 
	 ,MNG_CUST      =#{mng_cust},		USE_VPN            =#{use_vpn} 
	 ,TERM_START_DT =#{term_start_dt},	VPN_ADDR           =#{vpn_addr} 
	 ,TERM_END_DT   =#{term_end_dt},	VPN_ID             =#{vpn_id} 
	 ,VPN_PASS      =#{vpn_pass},		UPD_DATE           =SYSDATE                                                                                          
	 ,STORAGE_VOLUME=#{storage_volume},	UPD_ID             =#{reg_id} 
	 ,STORAGE_HOST  =#{storage_host}     
WHERE 1=1                                   
AND SEQ = #{seq}          
AND CUST_SEQ = #{cust_seq}

