MERGE INTO 
    CRM_NETWORK_HIST
USING DUAL 
    ON (NETWORK_SEQ = #{network_seq}  AND HIST_SEQ = #{hist_seq})
    WHEN MATCHED THEN     
        UPDATE SET
		    WORK_CUST = #{work_cust}
		    ,CUST_CHARGE = #{cust_charge}
		    ,WORK_TYPE = #{work_type}
		    ,WORK_TIME = #{work_time}
		    ,INFRA_GUBUN = #{infra_gubun}
		    ,EQUIPMENT_NM = #{equipment_nm}
		    ,HIST_ETC = #{hist_etc}
		    ,WORK_CONTENT = #{work_content}
		    ,REG_ID = #{reg_id}
		    ,WORK_CHARGE = #{work_charge}
		    ,UPD_DATE = SYSDATE
		    ,UPD_ID = #{reg_id}
		    ,END_DT = #{end_dt}
		    ,STR_DT = #{str_dt}
    WHEN NOT MATCHED THEN
        INSERT (
	          HIST_SEQ       ,END_DT        
			 ,CUST_SEQ       ,WORK_TIME     
			 ,WORK_TYPE      ,TIME_GUBUN    
			 ,INFRA_GUBUN    ,HIST_ETC      
			 ,EQUIPMENT_NM   ,REG_ID        
			 ,WORK_CONTENT   ,REG_DATE      
			 ,WORK_CHARGE    ,NETWORK_SEQ   
			 ,WORK_CUST      ,STR_DT        
			 ,CUST_CHARGE    
		)
        VALUES(
			 MAX_NETWORK_HIST_SEQ.NEXTVAL 		,#{end_dt}  
			 ,#{cust_seq} 		,#{work_time}  
			 ,#{work_type} 		,#{time_gubun}  
			 ,#{infra_gubun} 	,#{hist_etc}  
			 ,#{equipment_nm} 	,#{reg_id}  
			 ,#{work_content} 	,#{reg_date}  
			 ,#{work_charge} 	,#{network_seq}  
			 ,#{work_cust} 		,#{str_dt}  
			 ,#{cust_charge}
        )

