SELECT OUT_TB.* FROM( SELECT IN_TB.* , ROW_NUMBER() OVER(ORDER BY IN_TB.RETIREDT ) AS RNUM FROM (SELECT COMPANYID -- 회사CD , COMPANY_NM --회사NM , USERID -- 사번 , USERNM -- 성명 , DEPTID -- 부서CD , DEPTNM -- 부서명 , RETIREDT -- 퇴사일자 , DECODE(CNT,'1','C002','0','C001') AS RETIRE_FLAG --퇴사 FLAG(C002 : 사간이동, C001 : 퇴사) FROM ( SELECT ROW_NUMBER() OVER(PARTITION BY EMP.USERID ORDER BY EMP.STA_YMD DESC) ROW_NUM , EMP.COMPANYID , (SELECT CODE_NAME FROM CRM_CODE_DETAIL WHERE EMP.COMPANYID = CODE AND CODE_GROUP = 'RETIRE' AND P_CODE = 'RT02') AS COMPANY_NM , EMP.USERID , EMP.USERNM , EMP.DEPTID , DPT.DEPTNM , EMP.RETIREDT , EMP.STA_YMD , EMP.END_YMD , (SELECT COUNT(*) FROM CWC_USER_NEW@DL_JWHR_H552 WHERE IN_OFFI_YN = 'Y' AND USERID = EMP.USERID AND SYSDATE BETWEEN STA_YMD AND END_YMD) AS CNT FROM CWC_USER_NEW@DL_JWHR_H552 EMP, CWC_DPT_NEW@DL_JWHR_H552 DPT WHERE EMP.DEPTID = DPT.DEPTID AND EMP.COMPANYID = DPT.COMPANYID AND EMP.RETIREDT BETWEEN DPT.STA_YMD AND DPT.END_YMD AND EMP.USERID = NVL(NULL , EMP.USERID) AND DPT.COMPANYID = NVL(NULL , DPT.COMPANYID) AND EMP.IN_OFFI_YN = 'N' ) WHERE ROW_NUM = '1' ORDER BY RETIREDT )IN_TB WHERE 1=1
AND USERID = #{userid}
AND RETIREDT = #{retiredt}
)OUT_TB


