MERGE INTO CRM_RETIRE_MGT
    USING DUAL
    ON( 
    	EMP_NO = #{emp_no} 
        AND RETIRE_DATE = #{retire_date} 
        AND CHECK_CD = #{check_cd}
        )
    WHEN MATCHED THEN
        UPDATE SET
            CHECK_YN = #{check_yn}
            , NOTE = #{note}
            , REG_ID = #{reg_id}


            , REG_DATE = #{reg_date}


            , REG_DATE = DECODE(#{check_yn}, 'Y', TO_CHAR(SYSDATE,'YYYY-MM-DD HH24:MI'), DECODE(#{note}, NULL, NULL, TO_CHAR(SYSDATE,'YYYY-MM-DD HH24:MI')) )


    WHEN NOT MATCHED THEN
        INSERT(
                EMP_NO
              , RETIRE_DATE
              , CHECK_CD
              , CHECK_YN
              , REG_ID
              , REG_DATE
              , NOTE
              )
        VALUES( 
                #{emp_no}
              , #{retire_date}
              , #{check_cd}
              , #{check_yn}
              , DECODE(#{check_yn}, 'Y', #{reg_id}, DECODE(#{note}, NULL, NULL, #{reg_id}) )
              , DECODE(#{check_yn}, 'Y', TO_CHAR(SYSDATE,'YYYY-MM-DD HH24:MI'), DECODE(#{note}, NULL, NULL, TO_CHAR(SYSDATE,'YYYY-MM-DD HH24:MI')) )
              , #{note}
              )
